import { motion } from "framer-motion";
import { projects } from "../data/data";
import { FaExternalLinkAlt, FaGithub } from "react-icons/fa";

export default function Projects() {
  return (
    <section id="projects" className="py-24 bg-white/[0.02]">
      <div className="max-w-6xl mx-auto px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="text-center mb-16"
        >
          <h2 className="text-3xl sm:text-4xl font-bold">Projects</h2>
          <div className="w-16 h-0.5 bg-gradient-to-r from-indigo-500 to-cyan-500 mx-auto mt-4" />
        </motion.div>

        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-5">
          {projects.map((p, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.08 }}
              whileHover={{ y: -4 }}
              className="glass rounded-xl p-5 flex flex-col hover:border-white/15 transition-all duration-300 group"
            >
              {/* Top */}
              <div className="flex items-start justify-between mb-3">
                <span
                  className="text-xs font-medium px-2.5 py-1 rounded-full border"
                  style={{
                    color: p.color,
                    borderColor: p.color + "40",
                    background: p.color + "15",
                  }}
                >
                  {p.badge}
                </span>
                <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                  <a href={p.link} target="_blank" rel="noreferrer"
                    className="text-gray-500 hover:text-white transition-colors text-sm">
                    <FaGithub />
                  </a>
                  <a href={p.link} target="_blank" rel="noreferrer"
                    className="text-gray-500 hover:text-white transition-colors text-sm">
                    <FaExternalLinkAlt />
                  </a>
                </div>
              </div>

              <h3 className="font-semibold text-white mb-2">{p.title}</h3>
              <p className="text-gray-400 text-sm leading-relaxed mb-4 flex-1">{p.desc}</p>

              {/* Tags */}
              <div className="flex flex-wrap gap-1.5">
                {p.tags.map((t) => (
                  <span key={t} className="font-code text-xs px-2 py-0.5 rounded bg-white/5 text-gray-500 border border-white/5">
                    {t}
                  </span>
                ))}
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
